import glob
from tensorboard.backend.event_processing import event_file_loader

for path in sorted(glob.glob("logs/tensorboard/HybridPPO_seed42_*/events.out.tfevents.*")):
    print("====", path)
    loader = event_file_loader.EventFileLoader(path)
    count = 0
    last_step = {}
    tags = set()
    for event in loader.Load():
        count += 1
        if event.HasField('summary'):
            for v in event.summary.value:
                tags.add(v.tag)
                last_step[v.tag] = (event.step, event.wall_time, v.simple_value if v.HasField('simple_value') else None)
    print("total events:", count)
    for tag in sorted(tags):
        print(" tag:", tag, "-> last:", last_step[tag])
